import { captureClipboardImage } from "../../attachments/clipboard-image.js";
import {
  formatAttachmentReference,
  stabilizeDroppedImagesInText,
} from "../../ui/mentions.js";
import type { AppServices } from "../../ui-core/bootstrap/composition-root.js";
import { notify } from "../../ui-core/notify.js";

interface ComposerEditor {
  readonly plainText: string;
  readonly cursorOffset: number;
  insertText(text: string): void;
  focus(): void;
}

interface EditorRef {
  readonly current: ComposerEditor | null;
}

interface PreventableEvent {
  preventDefault(): void;
}

interface ComposerImagePaste {
  handleChord(
    chord: string,
    overlayKind: string,
    key: PreventableEvent,
  ): boolean;
  handlePaste(text: string, event: PreventableEvent): boolean;
  handleDroppedImages(text: string, event: PreventableEvent): boolean;
}

const activePastes = new WeakSet<AppServices>();

export function createComposerImagePaste(
  services: AppServices,
  editorRef: EditorRef,
  refresh: () => void,
): ComposerImagePaste {
  const pasteImage = (): void => {
    if (activePastes.has(services)) return;
    activePastes.add(services);
    setImmediate(() => {
      const result = captureClipboardImage();
      activePastes.delete(services);
      if (!result.ok) {
        notify(services, result.reason, {
          key: "image-paste",
          level: "warn",
          durationMs: 2600,
        });
        return;
      }
      const editor = editorRef.current;
      if (!editor) return;
      const before = editor.plainText[editor.cursorOffset - 1] ?? "";
      const leadingSpace = before && !/\s/.test(before) ? " " : "";
      const reference = formatAttachmentReference(result.path);
      editor.insertText(`${leadingSpace}${reference} `);
      services.focus.focusRegion("composer");
      editor.focus();
      notify(services, "Image attached from clipboard", {
        key: "image-paste",
        durationMs: 1600,
      });
      queueMicrotask(refresh);
    });
  };

  return {
    handleChord(chord, overlayKind, key) {
      if (overlayKind !== "none" || chord !== "ctrl+v") return false;
      key.preventDefault();
      services.focus.focusRegion("composer");
      editorRef.current?.focus();
      pasteImage();
      return true;
    },
    handlePaste(text, event) {
      if (text.trim()) return false;
      event.preventDefault();
      pasteImage();
      return true;
    },
    handleDroppedImages(text, event) {
      if (!text.trim()) return false;
      const { text: rewritten, images } = stabilizeDroppedImagesInText(text);
      if (images.length === 0) return false;
      event.preventDefault();
      const editor = editorRef.current;
      if (!editor) return true;
      const before = editor.plainText[editor.cursorOffset - 1] ?? "";
      const leadingSpace = before && !/\s/.test(before) ? " " : "";
      editor.insertText(`${leadingSpace}${rewritten} `);
      services.focus.focusRegion("composer");
      editor.focus();
      notify(
        services,
        images.length > 1
          ? `${images.length} images attached`
          : "Image attached",
        { key: "image-paste", durationMs: 1600 },
      );
      queueMicrotask(refresh);
      return true;
    },
  };
}

export function composerDraftOverflows(
  contentLines: number,
  visibleRows: number,
): boolean {
  return Math.max(1, contentLines) > Math.max(1, visibleRows);
}

/** Multi-line draft (newlines or soft-wrap) owns the wheel — never the chat. */
export function composerOwnsWheel(contentLines: number): boolean {
  return Math.max(1, contentLines) > 1;
}

/** Next viewport Y for an overflowing draft; undefined if nothing to scroll. */
export function nextComposerScrollOffset(opts: {
  readonly offsetY: number;
  readonly viewportHeight: number;
  readonly totalLines: number;
  readonly direction: "up" | "down" | string;
  readonly delta?: number | undefined;
  readonly lineStep?: number | undefined;
}): number | undefined {
  const height = Math.max(1, opts.viewportHeight);
  const total = Math.max(0, opts.totalLines);
  const maxOffset = Math.max(0, total - height);
  if (maxOffset <= 0) return undefined;
  const step = Math.max(1, opts.delta ?? 1) * Math.max(1, opts.lineStep ?? 3);
  const cur = Math.max(0, Math.min(maxOffset, opts.offsetY));
  if (opts.direction === "up") return Math.max(0, cur - step);
  if (opts.direction === "down") return Math.min(maxOffset, cur + step);
  return undefined;
}

/** Minimal editor surface used for draft-internal wheel scroll. */
export interface ComposerWheelEditor {
  readonly lineCount?: number;
  readonly virtualLineCount?: number;
  readonly plainText?: string;
  readonly editorView: {
    getViewport(): {
      offsetY: number;
      offsetX: number;
      height: number;
      width: number;
    };
    getTotalVirtualLineCount?: () => number;
    setViewport(
      x: number,
      y: number,
      width: number,
      height: number,
      moveCursor?: boolean,
    ): void;
  };
  moveCursorUp(): unknown;
  moveCursorDown(): unknown;
}

/** Best-effort visual line count from the live editor (React state can lag). */
export function measureComposerLines(
  editor: ComposerWheelEditor | null | undefined,
  contentLinesFallback: number,
): number {
  if (!editor) return Math.max(1, contentLinesFallback);
  const fromView =
    editor.editorView.getTotalVirtualLineCount?.() ??
    editor.virtualLineCount ??
    0;
  const logical = editor.lineCount ?? 0;
  const hardBreaks = editor.plainText
    ? Math.max(1, editor.plainText.split("\n").length)
    : 1;
  return Math.max(1, contentLinesFallback, fromView, logical, hardBreaks);
}

/**
 * Scroll the draft when the composer owns the wheel.
 * Returns true when chat must NOT scroll (multi-line / overflow draft).
 */
export function tryScrollComposerDraft(
  editor: ComposerWheelEditor,
  opts: {
    readonly contentLines: number;
    readonly visibleRows: number;
    readonly direction: "up" | "down" | string;
    readonly delta?: number | undefined;
  },
): boolean {
  const lines = measureComposerLines(editor, opts.contentLines);
  if (!composerOwnsWheel(lines) && !composerDraftOverflows(lines, opts.visibleRows)) {
    return false;
  }

  const steps = Math.max(1, opts.delta ?? 1) * 3;

  if (composerDraftOverflows(lines, opts.visibleRows)) {
    try {
      const view = editor.editorView;
      const vp = view.getViewport();
      const total =
        view.getTotalVirtualLineCount?.() ??
        editor.virtualLineCount ??
        lines;
      const nextY = nextComposerScrollOffset({
        offsetY: vp.offsetY,
        viewportHeight: vp.height || opts.visibleRows,
        totalLines: total,
        direction: opts.direction,
        delta: opts.delta,
      });
      if (nextY !== undefined && nextY !== vp.offsetY) {
        view.setViewport(vp.offsetX, nextY, vp.width, vp.height, false);
        return true;
      }
    } catch {
      // Fall through to cursor-based scroll.
    }
  }

  if (opts.direction === "up") {
    for (let i = 0; i < steps; i++) editor.moveCursorUp();
    return true;
  }
  if (opts.direction === "down") {
    for (let i = 0; i < steps; i++) editor.moveCursorDown();
    return true;
  }
  return true;
}

/** Wheel delta → transcript scroll steps (shared by composer + app). */
export function wheelChatDelta(
  direction: "up" | "down" | string,
  delta?: number,
): number {
  const step = Math.max(1, delta ?? 1) * 3;
  if (direction === "up") return -step;
  if (direction === "down") return step;
  return 0;
}

/**
 * Resolve composer wheel: "draft" | "chat" | "none".
 * Unfocused composer never scrolls the draft (avoids dual scroll with chat).
 */
export function resolveComposerWheelTarget(opts: {
  readonly composerFocused: boolean;
  readonly editor: ComposerWheelEditor | null | undefined;
  readonly contentLines: number;
  readonly visibleRows: number;
}): "draft" | "chat" {
  if (!opts.composerFocused || !opts.editor) return "chat";
  const lines = measureComposerLines(opts.editor, opts.contentLines);
  if (
    composerOwnsWheel(lines) ||
    composerDraftOverflows(lines, opts.visibleRows)
  ) {
    return "draft";
  }
  return "chat";
}

export type TextareaActionName =
  | "submit"
  | "newline"
  | "delete-to-line-start"
  | "delete-to-line-end"
  | "delete-line"
  | "delete-word-backward"
  | "delete-word-forward"
  | "select-all"
  | "select-word-backward"
  | "select-word-forward"
  | "select-line-home"
  | "select-line-end";

export interface TextareaKeyBindingLike {
  readonly name: string;
  readonly ctrl?: boolean;
  readonly shift?: boolean;
  readonly meta?: boolean;
  readonly super?: boolean;
  readonly action: TextareaActionName;
}

const ENTER_NAMES = ["return", "kpenter"] as const;

export function buildComposerTextareaOverrides(): TextareaKeyBindingLike[] {
  const overrides: TextareaKeyBindingLike[] = [];
  for (const name of ENTER_NAMES) {
    // Bare Enter → submit. Newline chords cover every OS/terminal that can
    // report a modifier on Return (Shift, Alt/Option/meta, Ctrl).
    overrides.push({ name, action: "submit" });
    overrides.push({ name, shift: true, action: "newline" });
    overrides.push({ name, meta: true, action: "newline" });
    overrides.push({ name, ctrl: true, action: "newline" });
  }

  // ── Word kill: Option/Alt (+Backspace/Delete)
  // On macOS terminals, Option almost always arrives as `meta`.
  overrides.push({
    name: "backspace",
    meta: true,
    action: "delete-word-backward",
  });
  overrides.push({
    name: "delete",
    meta: true,
    action: "delete-word-forward",
  });

  // ── Full line kill: Cmd (super) and Ctrl (Windows / some terminals)
  // OpenTUI default maps ctrl+backspace → word; override to whole line.
  overrides.push({ name: "backspace", super: true, action: "delete-line" });
  overrides.push({ name: "delete", super: true, action: "delete-line" });
  overrides.push({ name: "backspace", ctrl: true, action: "delete-line" });
  overrides.push({ name: "delete", ctrl: true, action: "delete-line" });

  // readline Ctrl+U and many terminals' Cmd+Backspace → Ctrl+U encoding.
  overrides.push({ name: "u", ctrl: true, action: "delete-line" });
  // Ctrl+K keeps "kill to end of line" (readline) for power users.
  overrides.push({ name: "k", ctrl: true, action: "delete-to-line-end" });

  // ── Selection
  // OpenTUI's defaults bind shift+arrow and shift+home/end, but never bind
  // `select-all` or the word/line selection actions, so those were unreachable.
  // Cmd+A is the platform-native select-all; Ctrl+Alt+A covers terminals that
  // do not deliver super, without shadowing readline Ctrl+A (line-home).
  overrides.push({ name: "a", super: true, action: "select-all" });
  overrides.push({ name: "a", ctrl: true, meta: true, action: "select-all" });
  // Option/Alt + Shift + arrow → extend by word (macOS/most terminals).
  overrides.push({
    name: "left",
    meta: true,
    shift: true,
    action: "select-word-backward",
  });
  overrides.push({
    name: "right",
    meta: true,
    shift: true,
    action: "select-word-forward",
  });
  // Cmd + Shift + arrow → extend to the visual line edge.
  overrides.push({
    name: "left",
    super: true,
    shift: true,
    action: "select-line-home",
  });
  overrides.push({
    name: "right",
    super: true,
    shift: true,
    action: "select-line-end",
  });

  return overrides;
}

